CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, source_kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL, path text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT true, last_error text, last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid REFERENCES projects(id) ON DELETE CASCADE, source_id uuid REFERENCES sources(id) ON DELETE SET NULL, external_key text NOT NULL, title text NOT NULL, status text NOT NULL DEFAULT 'unknown', started_at timestamptz, ended_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id, external_key));
CREATE TABLE IF NOT EXISTS agents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, external_key text NOT NULL, name text NOT NULL, role text, UNIQUE(session_id, external_key));
CREATE TABLE IF NOT EXISTS events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, agent_id uuid REFERENCES agents(id) ON DELETE SET NULL, external_key text NOT NULL, schema_version text NOT NULL DEFAULT 'aw.event.v1', event_type text NOT NULL, status text, sequence integer NOT NULL, occurred_at timestamptz, summary text, content text, payload jsonb NOT NULL DEFAULT '{}'::jsonb, content_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id, external_key));
CREATE TABLE IF NOT EXISTS edges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, from_agent_id uuid REFERENCES agents(id) ON DELETE CASCADE, to_agent_id uuid REFERENCES agents(id) ON DELETE CASCADE, relation text NOT NULL DEFAULT 'handoff', event_id uuid REFERENCES events(id) ON DELETE SET NULL, UNIQUE(session_id, from_agent_id, to_agent_id, relation, event_id));
CREATE INDEX IF NOT EXISTS events_session_sequence_idx ON events(session_id, sequence);
